  "issues": [
    {
      "file": "jobwatch/db.py",
      "lines": "74-80",
      "severity": "high",
      "description": "Same-state reingests are treated as unchanged when only resources, user, partition, submit/start, GPU count, or exit code change, leaving stale accounting data in SQLite."
