      "file": "jobwatch/reports.py",
      "lines": "14, 65, 83, 101, 115, 119-121",
      "severity": "high",
      "description": "Timestamp filtering and newest-record logic compare ISO strings lexically, which gives wrong results for timezone-aware timestamps instead of comparing absolute datetimes."
    },
    {
      "file": "jobwatch/parser.py",
      "lines": "118-126",
      "severity": "medium",
      "description": "Timezone-aware timestamps are accepted and preserved without normalization, feeding values into report queries that cannot compare offsets correctly."
    },
